// Cleans each enquiry and checks it against the leads already in the sheet.
// Works with the n8n form, Google Forms (via the Google Sheets trigger) or Jotform: it finds fields by name.
const s = $('Settings').first().json;
const tz = s.timezone || 'Asia/Singapore';

const text = v => {
  if (v === null || v === undefined) return '';
  if (Array.isArray(v)) return v.map(text).filter(Boolean).join(', ');
  if (typeof v === 'object') return Object.values(v).map(text).filter(Boolean).join(' ');
  return String(v).replace(/\s+/g, ' ').trim();
};
function pick(obj, patterns, exclude) {
  for (const p of patterns) {
    for (const [k, v] of Object.entries(obj)) {
      if (exclude && exclude.test(k)) continue;
      if (p.test(k) && text(v)) return text(v);
    }
  }
  return '';
}
// Singapore numbers: 8 digits starting 6, 8 or 9, stored as "+65 9123 4567". Overseas numbers kept with their code.
function cleanPhone(raw) {
  const typed = text(raw);
  if (!typed) return { phone: '', digits: '', note: '' };
  let d = typed.replace(/[^\d+]/g, '');
  if (d.startsWith('00')) d = '+' + d.slice(2);
  if (d.startsWith('+') && !d.startsWith('+65')) {
    const n = d.replace(/\D/g, '');
    if (n.length >= 8 && n.length <= 15) return { phone: '+' + n, digits: n, note: 'Overseas number' };
    return { phone: '', digits: '', note: 'Phone number looks wrong, check it' };
  }
  d = d.replace(/\D/g, '');
  if (d.length === 10 && d.startsWith('65')) d = d.slice(2);
  if (/^[689]\d{7}$/.test(d)) return { phone: '+65 ' + d.slice(0, 4) + ' ' + d.slice(4), digits: '65' + d, note: '' };
  return { phone: '', digits: '', note: 'Phone number looks wrong, check it' };
}
function cleanEmail(raw) {
  const e = text(raw).toLowerCase().replace(/\s/g, '');
  if (!e) return { email: '', note: '' };
  if (/^[^@]+@[^@]+\.[a-z]{2,}$/.test(e)) return { email: e, note: '' };
  return { email: '', note: 'Email looks wrong: ' + e };
}
function stamp(d) {
  const p = new Intl.DateTimeFormat('en-GB', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(d);
  const g = t => p.find(x => x.type === t).value;
  return `${g('year')}-${g('month')}-${g('day')} ${g('hour')}:${g('minute')}`;
}

// Index the leads already in the sheet (oldest row wins, so the original owner keeps the lead)
const byEmail = new Map(), byPhone = new Map();
for (const r of $('Get existing leads').all().map(i => i.json)) {
  const e = cleanEmail(r['Email']).email;
  const p = cleanPhone(r['Phone']).digits;
  if (e && !byEmail.has(e)) byEmail.set(e, r);
  if (p && !byPhone.has(p)) byPhone.set(p, r);
}

const out = [];
const seenEmail = new Map(), seenPhone = new Map();   // duplicates inside the same batch
for (const item of $('On form submission').all()) {
  const f = item.json;
  const name = pick(f, [/^(full |your )?name$/i, /name/i], /company|business|user ?name|file/i);
  const company = pick(f, [/company|business|organi[sz]ation/i]);
  const message = pick(f, [/how can we help|message|enquiry|inquiry|comment|details|requirement|question/i]);
  const em = cleanEmail(pick(f, [/^e-?mail/i, /e-?mail/i]));
  const typedPhone = pick(f, [/mobile|phone|whatsapp|contact (no|number)|handphone|\bhp\b/i]);
  const ph = cleanPhone(typedPhone);
  if (!name && !em.email && !typedPhone && !message) continue;       // empty or bot submission

  const notes = [em.note, ph.note].filter(Boolean);
  if (!em.email && !ph.digits) notes.push('No valid email or phone: check the enquiry');
  const when = f.submittedAt || f.Timestamp || f.created_at;
  const lead = {
    receivedAt: stamp(when && !isNaN(new Date(when)) ? new Date(when) : new Date()),
    name: name || '(no name given)', company, email: em.email, phone: ph.phone, phoneDigits: ph.digits,
    phoneTyped: typedPhone, message, source: s.source || 'Website form', status: 'New',
    notes: notes.join('; '), isNew: true, isRepeat: false,
  };

  const earlier = (em.email && byEmail.get(em.email)) || (ph.digits && byPhone.get(ph.digits));
  let batchIdx;
  if (em.email && seenEmail.has(em.email)) batchIdx = seenEmail.get(em.email);
  else if (ph.digits && seenPhone.has(ph.digits)) batchIdx = seenPhone.get(ph.digits);
  if (earlier) {
    Object.assign(lead, { isNew: false, isRepeat: true, status: 'Repeat enquiry',
      existingOwnerName: text(earlier['Assigned to']), existingOwnerEmail: text(earlier['Assigned email']).toLowerCase(),
      firstReceived: text(earlier['Received']) });
  } else if (batchIdx !== undefined) {
    Object.assign(lead, { isNew: false, isRepeat: true, status: 'Repeat enquiry', repeatOfBatch: batchIdx,
      firstReceived: out[batchIdx].json.receivedAt });
  }
  const idx = out.length;
  if (em.email && !seenEmail.has(em.email)) seenEmail.set(em.email, idx);
  if (ph.digits && !seenPhone.has(ph.digits)) seenPhone.set(ph.digits, idx);
  out.push({ json: lead, pairedItem: { item: 0 } });
}
return out;

// Gives each new lead to the next salesperson in turn. Repeat enquiries stay with the person who already has them.
const s = $('Settings').first().json;
const team = String(s.salespeople || '').split(/[,;\n]/).map(x => x.trim()).filter(Boolean).map(x => {
  const m = x.match(/^(.*?)\s*<([^>]+)>$/);
  return m ? { name: m[1].trim() || m[2].trim(), email: m[2].trim().toLowerCase() } : { name: x.split('@')[0], email: x.toLowerCase() };
}).filter(p => p.email.includes('@'));
if (!team.length) throw new Error('Add at least one salesperson in Settings, written as Name <email>');

const store = $getWorkflowStaticData('global');   // remembers whose turn it is (saved for active workflows only)
const owners = [];
return $input.all().map((item, i) => {
  const lead = item.json;
  let owner, how;
  if (lead.isRepeat && lead.repeatOfBatch !== undefined) {
    owner = owners[lead.repeatOfBatch]; how = 'Repeat enquiry, same salesperson';
  } else if (lead.isRepeat && lead.existingOwnerEmail) {
    owner = team.find(p => p.email === lead.existingOwnerEmail) || { name: lead.existingOwnerName || lead.existingOwnerEmail, email: lead.existingOwnerEmail };
    how = 'Repeat enquiry, same salesperson';
  } else if (lead.isRepeat) {
    owner = { name: s.managerName || 'Manager', email: String(s.managerEmail).toLowerCase() }; how = 'Repeat enquiry, lead had no owner';
  } else {
    // Position of whoever went last. The stored position is used when it still matches, so a person listed twice gets two turns.
    const last = (team[store.lastIndex] && team[store.lastIndex].email === store.lastAssigned)
      ? store.lastIndex : team.findIndex(p => p.email === store.lastAssigned);
    const next = (last + 1) % team.length;
    owner = team[next];
    store.lastAssigned = owner.email;
    store.lastIndex = next;
    how = 'Round robin';
  }
  owners[i] = owner;
  return { json: { ...lead, ownerName: owner.name, ownerEmail: owner.email, assignedBy: how }, pairedItem: { item: i } };
});

// Writes the auto-reply to the enquirer and the heads-up to the salesperson.
const s = $('Settings').first().json;
const l = $json;
const first = (l.name || '').split(' ')[0];
const hello = l.name && l.name !== '(no name given)' ? `Hi ${first},` : 'Hello,';
const ownerFirst = l.ownerName.split(' ')[0];
const quoted = l.message ? `\n\nFor reference, you wrote:\n"${l.message}"` : '';

const replyBody = l.isRepeat
  ? `${hello}\n\nThank you for getting in touch again. ${ownerFirst} already has your earlier enquiry and will get back to you ${s.replyWithin}.${quoted}\n\nIf it is urgent, call or WhatsApp us on ${s.companyPhone}.\n\nBest regards,\n${l.ownerName}\n${s.companyName}`
  : `${hello}\n\nThank you for contacting ${s.companyName}. We have your enquiry, and ${ownerFirst} from our team will get back to you ${s.replyWithin}.${quoted}\n\nIf it is urgent, call or WhatsApp us on ${s.companyPhone}.\n\nBest regards,\n${l.ownerName}\n${s.companyName}`;

const noContact = !l.email && !l.phoneDigits;
const lines = [
  `Name: ${l.name}`,
  `Company: ${l.company || '-'}`,
  `Email: ${l.email || '(none given)'}`,
  `Phone: ${l.phone || '(none given)'}${l.phoneDigits ? '   WhatsApp: https://wa.me/' + l.phoneDigits : ''}`,
  l.phoneTyped && !l.phone ? `Phone as typed: ${l.phoneTyped}` : null,
  `Received: ${l.receivedAt}`,
  l.notes ? `Check: ${l.notes}` : null,
  '',
  `Enquiry:\n${l.message || '(no message)'}`,
  '',
  l.email ? 'An auto-reply has gone out in your name, so reply to them directly.'
    : noContact ? 'No auto-reply was sent and there is no valid email or phone. The manager is copied so someone decides what to do.'
    : 'No auto-reply was sent because there is no valid email. Call or WhatsApp them.',
  l.isRepeat ? `This person first contacted us on ${l.firstReceived || 'an earlier date'}. No new row was added to the Leads sheet.` : `Lead sheet: ${s.leadsSheetUrl}\nPlease update the Status column once you have made contact.`,
].filter(x => x !== null);

return { json: {
  ...l,
  hasEmail: !!l.email,
  replyTo: l.email,
  replySubject: l.isRepeat ? `We have your message, ${s.companyName}` : `Thank you for your enquiry, ${s.companyName}`,
  replyBody,
  notifyCc: noContact ? s.managerEmail : '',
  notifySubject: l.isRepeat
    ? `Repeat enquiry from ${l.name}${l.company ? ', ' + l.company : ''} (your lead)`
    : `${l.notes ? '[Check details] ' : ''}New lead for you: ${l.name}${l.company ? ', ' + l.company : ''}`,
  notifyBody: lines.join('\n'),
}};
